CREATE OR REPLACE FUNCTION update_margin_util() RETURNS TRIGGER AS $$
DECLARE
    v_marg_sum real;
    v_init_margin numeric;
    v_margin_util numeric;
BEGIN
    -- Get the sum of marg_sum for the user associated with this order
    SELECT COALESCE(SUM(ab."marg_sum"), 0) INTO v_marg_sum
    FROM orders o
    JOIN accountbalances ab ON o."UserRef" = ab."userTAG"
    WHERE o."ORD_STAMP" = NEW."ordStamp";

    -- Get initial margin required from JSONB
    v_init_margin := (NEW."margin_risk_profile"->>'initial_margin_pct')::numeric;

    -- Calculate margin utilization
    IF v_marg_sum > 0 THEN
        v_margin_util := ROUND(CAST(v_init_margin / v_marg_sum * 100 AS numeric), 2);
    ELSE
        v_margin_util := 0;
    END IF;

    -- Update the JSONB with the new margin utilization
    NEW."margin_risk_profile" := NEW."margin_risk_profile" || jsonb_build_object('margin_utilization', v_margin_util);

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

